SECS = {'Visualizações','Interações','Perfil','Anúncio','Respostas','Publicações','Recursos'}

# mapeamento nome -> coluna snake_case normalizada (quando inequívoco)
NORM = {
 'Visualizações':'visualizacoes','Visualizadores':'visualizadores','Alcance':'alcance',
 'Contas alcançadas':'contas_alcancadas','Interações':'interacoes','Interações com posts':'interacoes_posts',
 'Curtidas':'curtidas','Comentários':'comentarios','Compartilhamentos':'compartilhamentos',
 'Salvamentos':'salvamentos','Contas com engajamento':'contas_com_engajamento',
 'Atividade do perfil':'atividade_do_perfil','Visitas ao perfil':'visitas_ao_perfil',
 'Toques em links externos':'toques_links_externos','Toques no endereço comercial':'toques_endereco_comercial',
 'Seguidores':'seguidores','Novos seguidores':'novos_seguidores','Respostas':'respostas',
}

def num(v):
    v=v.replace('.','').replace(',','.')
    try: return int(v)
    except: return None

def parse_insights(txt):
    ls=[l.strip() for l in txt.split('\n') if l.strip()]
    sec=None; meta=[]; i=0
    while i<len(ls):
        l=ls[i]
        if l in SECS:
            sec=l; i+=1; continue
        nxt=ls[i+1] if i+1<len(ls) else None
        if nxt and re.fullmatch(r'[\d.,%+\s\-]+', nxt):
            meta.append({'secao':sec or '','nome_original':l,'valor_original':nxt})
            i+=2; continue
        # número pode inflar: título já é "X\n372"? Então linha atual pode ser valor de nome anterior
        if re.fullmatch(r'[\d.,%+\s\-]+', l):
            # se linha pura numérica e havia nome antes sem valor, emparelhar
            if meta and meta[-1]['valor_original']=='' and not meta[-1]['nome_original'].startswith('#'):
                meta[-1]['valor_original']=l
            i+=1; continue
        meta.append({'secao':sec or '','nome_original':l,'valor_original':''})
        i+=1
    return meta

def build_json(shortcode, url, tipo, datetime_iso, legenda, autor, coautores, colaborativo,
               insights_raw, status_data, status_insights, erro, fonte, coletado_em, extra=None):
    # data/hora America/Sao_Paulo
    dp=None; hp=None
    try:
        dt=datetime.datetime.fromisoformat(datetime_iso.replace('Z','+00:00'))
        dt=dt.astimezone(datetime.timezone(datetime.timedelta(hours=-3)))
        dp=dt.strftime('%Y-%m-%d'); hp=dt.strftime('%H:%M:%S')
    except Exception:
        status_data='NAO_CONFIRMADA'
    meta=parse_insights(insights_raw)
    metricas={}
    ausentes=[]
    for m in meta:
        n=norm(m['nome_original'])
        val=m['valor_original'].strip()
        if not val or val=='—' or val=='–':
            ausentes.append(m['nome_original'])
            continue
        if n:
            nums=num(val)
            metricas[n]=nums if nums is not None else val
    return {
      'shortcode':shortcode,'url':url,'data_publicacao':dp,'hora_publicacao':hp,
      'tipo_midia':tipo,'autor':autor,'colaborativo':colaborativo,'coautores':coautores,
      'legenda':legenda,'status_data':status_data,'status_insights':status_insights,'erro':erro,
      'metricas_ausentes':ausentes,'insights_raw':insights_raw,'melhores_metricas':metricas,
      'metricas_brutas':meta,'evidencia_data':{'time_datetime':datetime_iso,'og_ou_texto':extra.get('og') if extra else None},
      'coletado_em':coletado_em,'fonte':fonte,
    }

def norm(nome):
    n=NORM.get(nome)
    if n: return n
    # tenta match aproximado
    for k,v in NORM.items():
        if k.lower() in nome.lower() or nome.lower() in k.lower():
            return v
    return None","path":"C:\Users\Kevyn Lucas\Downloads\_acirv_agosto\_insights_builder.py"}

{"content":"import json, re, datetime, sys

SECS = {'Visualizações','Interações','Perfil','Anúncio','Respostas','Publicações','Recursos'}

# colunas normalizadas em snake_case (idênticas aos JSon existentes)
NORM = {
 'Visualizações':'visualizacoes','Visualizadores':'visualizadores','Alcance':'alcance',
 'Contas alcançadas':'contas_alcancadas','Interações':'interacoes','Interações com posts':'interacoes_posts',
 'Curtidas':'curtidas','Comentários':'comentarios','Compartilhamentos':'compartilhamentos',
 'Salvamentos':'salvamentos','Contas com engajamento':'contas_com_engajamento',
 'Atividade do perfil':'atividade_do_perfil','Visitas ao perfil':'visitas_ao_perfil',
 'Toques em links externos':'toques_em_links_externos','Toques no endereço comercial':'toques_no_endereco_comercial',
 'Seguidores':'novos_seguidores','Novos seguidores':'novos_seguidores','Respostas':'respostas',
 'Turbine este post':'promovido','Promover':'promovido','Impulsionar':'promovido',
}

def num(v):
    v=v.replace('.','').replace(',','.')
    try: return int(v)
    except: return None

def parse(dados):
    """dados: lista de linhas já limpas do body.innerText da página de insights."""
    ls=[l.strip() for l in dados if l.strip()]
    sec=None; rows=[]; i=0
    while i<len(ls):
        l=ls[i]
        if l in SECS:
            sec=l; i+=1; continue
        nxt=ls[i+1] if i+1<len(ls) else None
        if nxt and re.fullmatch(r'[\d.,%+\s\-]+', nxt):
            rows.append({'secao':sec or '','nome_original':l,'valor_original':nxt})
            i+=2; continue
        if re.fullmatch(r'[\d.,%+\s\-]+', l):
            if rows and rows[-1]['valor_original']=='':
                rows[-1]['valor_original']=l
            i+=1; continue
        rows.append({'secao':sec or '','nome_original':l,'valor_original':''})
        i+=1
    return rows

def normalize(rows):
    metricas={}; ausentes=[]
    for r in rows:
        v=r['valor_original'].strip()
        n=NORM.get(r['nome_original'])
        # match inexato
        if n is None:
            for k,c in NORM.items():
                if k.lower() in r['nome_original'].lower() or r['nome_original'].lower() in k.lower():
                    n=c; break
        if not v:
            ausentes.append(r['nome_original']); continue
        if n:
            numv=num(v)
            metricas[n]=numv if numv is not None else v
    return metricas, ausentes, rows

def build(shortcode, url, tipo, datetime_iso, legenda, autor, coautores, colaborativo,
          insights_raw, coletado_em, fonte, promovido=False, obs=None):
    rows=parse(insights_raw.split('\n'))
    metricas, ausentes, st=[]
    m, a, bruta = normalize(rows)
    # unifica promovido
    if 'promovido' in m:
        m['promovido']=True
    elif promovido:
        m['promovido']=True

    dp=None; hp=None; status_data='ok'
    try:
        dt=datetime.datetime.fromisoformat(datetime_iso.replace('Z','+00:00')).astimezone(datetime.timezone(datetime.timedelta(hours=-3)))
        dp=dt.strftime('%Y-%m-%d'); hp=dt.strftime('%H:%M:%S')
    except Exception:
        status_data='NAO_CONFIRMADA'
    base={
      'shortcode':shortcode,'url':url,'data_publicacao':dp,'hora_publicacao':hp,
      'tipo_midia':tipo.lower(),'autor':autor,'colaborativo':colaborativo,'coautores':coautores,
      'legenda':legenda,'status_data':status_data,'status_insights':'ok','erro':'',
      'metricas_ausentes':a if a else [],'insights_raw':insights_raw,'melhores_metricas':m,
      'evidencia_data':f"time datetime={datetime_iso}",
      'coletado_em':coletado_em,'fonte':fonte,
    }
    if obs: base['observacao']=obs
    return base

if __name__=='__main__':
    import json as j
    # CLI: python _insights_builder.py '<json del passos pela stdin>' -- recebe dict de metadados
    data=j.load(sys.stdin)
    out=build(**data)
    print(j.dumps(out,ensure_ascii=False))","path":"C:\Users\Kevyn Lucas\Downloads\_acirv_agosto\_insights_builder.py"}

